reference_solutions.javascript:
function canFinish(numCourses, prerequisites) {
  // Iterative DFS with three colours: 0 = new, 1 = on the current path, 2 = done.
  const adj = Array.from({ length: numCourses }, () => []);
  for (const [a, b] of prerequisites) adj[b].push(a);
  const color = new Array(numCourses).fill(0);
  for (let s = 0; s < numCourses; s++) {
    if (color[s]) continue;
    const stack = [[s, 0]];
    color[s] = 1;
    while (stack.length) {
      const top = stack[stack.length - 1];
      const u = top[0];
      if (top[1] < adj[u].length) {
        const v = adj[u][top[1]++];
        if (color[v] === 1) return false;
        if (color[v] === 0) { color[v] = 1; stack.push([v, 0]); }
      } else {
        color[u] = 2;
        stack.pop();
      }
    }
  }
  return true;
}
